with tempfile.TemporaryDirectory(prefix='mango-v45-tests-') as folder:
    base = Path(folder)
    for name, source in fixtures.items():
        file = base/name
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(source)
    for original in sorted(sdk.glob('sources/android-*/org/json/JSONObject.java'))[-1].parent.glob('*.java'):
        source = re.sub(r'^import (?:static )?(?:android\.|libcore\.).*;\n', '', original.read_text(), flags=re.M)
        source = re.sub(r'@(?:UnsupportedAppUsage|SystemApi|NonNull|Nullable)(?:\([^)]*\))?', '', source)
        file = base/'org/json'/original.name
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(source)
    production = root/'TMessagesProj/src/main/java/org/telegram/messenger'
    sources = list(base.rglob('*.java')) + [production/'MangoOutgoingTranslation.java', production/'MangoMessageReminderManager.java', reminder_editor, root/'Tools/tests/V45TranslationReminderTest.java', root/'Tools/tests/V45ReminderEditorTest.java']
    subprocess.run([str(java/'javac'), '-d', str(base/'classes'), *map(str, sources)], check=True)
    subprocess.run([str(java/'java'), '-cp', str(base/'classes'), 'org.telegram.messenger.V45TranslationReminderTest'], check=True)
    subprocess.run([str(java/'java'), '-cp', str(base/'classes'), 'org.telegram.messenger.V45ReminderEditorTest'], check=True)
